// Writes monuments.md: the state-by-state list in which each monument appears once, with its
// place, dates, style, material, view link and one home-view picture (assets/views/<id>.png).
// The whole file is generated from js/data.js; do not edit it by hand.
// .github/workflows/screenshots.yml runs this after shoot-views.mjs.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { MONUMENTS } from '../js/data.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'monuments.md');
const views = path.join(root, 'assets/views');
const site = 'https://monuments-of-india-nu.vercel.app';

// The catalogue's order. A state added later is appended, alphabetically, after these.
const STATE_ORDER = [
  'Andaman and Nicobar', 'Andhra Pradesh', 'Arunachal Pradesh', 'Assam', 'Bihar', 'Chandigarh',
  'Delhi', 'Goa', 'Gujarat', 'Himachal Pradesh', 'Jammu and Kashmir', 'Jharkhand', 'Karnataka',
  'Kerala', 'Ladakh', 'Madhya Pradesh', 'Maharashtra', 'Odisha', 'Punjab', 'Rajasthan', 'Sikkim',
  'Tamil Nadu', 'Telangana', 'Uttar Pradesh', 'Uttarakhand', 'West Bengal',
];

const byState = new Map();
for (const m of MONUMENTS) {
  if (!byState.has(m.state)) byState.set(m.state, []);
  byState.get(m.state).push(m);
}
for (const list of byState.values()) list.sort((a, b) => a.name.localeCompare(b.name, 'en'));
const extra = [...byState.keys()].filter((s) => !STATE_ORDER.includes(s)).sort((a, b) => a.localeCompare(b, 'en'));
const states = [...STATE_ORDER.filter((s) => byState.has(s)), ...extra];

const lines = [
  '# States and monuments',
  '',
  `${MONUMENTS.length} monuments in ${states.length} states and union territories. Each entry gives the place, the dates, the`,
  'architectural style and the main material, as shown on the monument\'s plaque and used by the',
  'filters (all from `js/data.js`), then the home view of the model.',
  '',
  'This page is generated by `tools/update-gallery.mjs`. [A GitHub Action](.github/workflows/screenshots.yml)',
  'redraws a monument\'s picture when that monument\'s own code changes. The pictures are the plain',
  'studio views from `tools/shoot-views.mjs`; the site adds shadows, photo textures and haze.',
  '',
  '[Back to the README](README.md) · [Architecture](architecture.md) · [The setting](realism.md) · [Components](components.md)',
  '',
  '## Contents',
  '',
  ...states.map((s) => `- [${s}](#${s.toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/ /g, '-')}) (${byState.get(s).length})`),
  '',
];
const missing = [];
for (const state of states) {
  const list = byState.get(state);
  lines.push(`## ${state}`, '');
  for (const m of list) {
    const file = `${m.id}.png`;
    if (!fs.existsSync(path.join(views, file))) missing.push(m.id);
    lines.push(
      `### ${m.name}`,
      '',
      `${m.place} · ${m.built} · ${m.style} · ${m.material} · [view in 3D](${site}/#${m.id})`,
      '',
      `![${m.name}](assets/views/${file})`,
      '',
    );
  }
}
fs.writeFileSync(outPath, lines.join('\n'));
if (missing.length) {
  console.error(`No picture for: ${missing.join(', ')}`);
  process.exit(1);
}
console.log(`monuments.md: ${MONUMENTS.length} monuments in ${states.length} states.`);
